create table public.ai_usage_windows(user_id uuid not null references auth.users(id) on delete cascade,task text not null,window_started_at timestamptz not null,request_count integer not null default 0,token_count bigint not null default 0,primary key(user_id,task,window_started_at));
create table public.idempotency_records(user_id uuid not null references auth.users(id) on delete cascade,operation text not null,idempotency_key text not null,response_snapshot jsonb,status text not null check(status in ('processing','completed','failed')),created_at timestamptz not null default now(),expires_at timestamptz not null,primary key(user_id,operation,idempotency_key));
create table public.transactional_outbox(id bigint generated always as identity primary key,aggregate_type text not null,aggregate_id text not null,event_type text not null,payload jsonb not null default '{}',status text not null default 'pending' check(status in ('pending','processing','completed','failed','dead_letter')),attempt_count integer not null default 0,available_at timestamptz not null default now(),locked_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
alter table public.ai_usage_windows enable row level security;alter table public.idempotency_records enable row level security;alter table public.transactional_outbox enable row level security;
create policy "users read own ai usage" on public.ai_usage_windows for select using(user_id=auth.uid());create policy "users read own idempotency" on public.idempotency_records for select using(user_id=auth.uid());
create or replace function public.consume_ai_quota(p_task text,p_request_id text) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();v_window timestamptz:=date_trunc('day',now());v_count integer;begin if v_user is null then return false;end if;if p_task not in ('career-coach','interviewer') or char_length(p_request_id)>100 then return false;end if;insert into public.ai_usage_windows(user_id,task,window_started_at,request_count) values(v_user,p_task,v_window,1) on conflict(user_id,task,window_started_at) do update set request_count=public.ai_usage_windows.request_count+1 returning request_count into v_count;return v_count<=40;end$$;
create or replace function public.record_ai_request_audit(p_user_id uuid,p_prompt_key text,p_prompt_version text,p_model_key text,p_request_id text,p_status text,p_latency_ms integer,p_input_tokens integer default null,p_output_tokens integer default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'forbidden';end if;insert into public.ai_request_audits(user_id,prompt_key,prompt_version,model_key,request_id,input_tokens,output_tokens,latency_ms,status) values(p_user_id,p_prompt_key,p_prompt_version,p_model_key,p_request_id,p_input_tokens,p_output_tokens,p_latency_ms,p_status);end$$;
revoke all on function public.consume_ai_quota(text,text) from public;grant execute on function public.consume_ai_quota(text,text) to authenticated;
revoke all on function public.record_ai_request_audit(uuid,text,text,text,text,text,integer,integer,integer) from public;grant execute on function public.record_ai_request_audit(uuid,text,text,text,text,text,integer,integer,integer) to authenticated;
create index outbox_ready_idx on public.transactional_outbox(status,available_at) where status in ('pending','failed');create index ai_usage_cleanup_idx on public.ai_usage_windows(window_started_at);
revoke all on function public.is_active_org_member(uuid) from public;grant execute on function public.is_active_org_member(uuid) to authenticated;
revoke all on function public.is_active_employer_member(uuid) from public;grant execute on function public.is_active_employer_member(uuid) to authenticated;
revoke all on function public.is_active_program_member(uuid) from public;grant execute on function public.is_active_program_member(uuid) to authenticated;
revoke all on function public.is_platform_staff() from public;grant execute on function public.is_platform_staff() to authenticated;
revoke all on function public.can_manage_application(uuid) from public;grant execute on function public.can_manage_application(uuid) to authenticated;
